1314	```Plain Text
1315	// 分配SKB缓冲区用于硬件发送
1316	skb = rltk_wlan_alloc_skb(len);
1317	// 临界区保护分配结果检查
1318	rtw_enter_critical_bh(&tx_queue->lock, &irqL);
1319	if (!skb)  // SKB分配失败处理
1320	{
1321	    rtw_exit_critical_bh(&tx_queue->lock, &irqL);
1322	    
1323	    // 减少发送计数
1324	    save_and_cli(&irqL1);
1325	    rltk_wlan_tx_dec(devidx);           
1326	    restore_flags(irqL1);
1327	    
1328	    // 短暂休眠后重试
1329	    rtw_msleep_os(1);
