1699	  for (i = 0; i < nitems(g_wapi_commands); i++)
1700	    {
1701	      FAR const struct wapi_command_s *cmd = &g_wapi_commands[i];
1702	      if (strcmp(cmdname, cmd->name) == 0)
1703	        {
1704	          wapicmd = cmd;
