1710	    {
1711	      WAPI_ERROR("ERROR: Unsupported command: %s\n", cmdname);
1712	      wapi_showusage(argv[0], EXIT_FAILURE);
1713	    }
1714	
1715	  if (wapicmd->maxargs + 2 < argc)
1716	    {
1717	      WAPI_ERROR("ERROR: Garbage at end of command ignored\n");
1718	    }
1719	  else if (wapicmd->minargs + 2 > argc)
1720	    {
1721	      WAPI_ERROR("ERROR: Missing required command options: %s\n",
1722	                 cmdname);
1723	      wapi_showusage(argv[0], EXIT_FAILURE);
1724	    }
1725	
1726	  /* Special case the help command which has no arguments, no handler,
1727	   * and does not need a socket.
1728	   */
1729	
1730	  if (wapicmd->handler == NULL)
1731	    {
1732	      wapi_showusage(argv[0], EXIT_SUCCESS);
1733	    }
1734	
1735	  /* Create a communication socket */
1736	    
1737	  sock = wapi_make_socket();
