1743	
1744	  ret = wapicmd->handler(sock, argc - 2, argc == 2 ? NULL : &argv[2]);
1745	  if (ret < 0)
1746	    {
1747	      WAPI_ERROR("ERROR: Process command (%s) failed.\n", cmdname);
1748	    }
1749	
1750	  /* Close communication socket */
1751	
1752	  close(sock);
1753	  return ret;
1754	}
